const links = phi.query("a", { fields: ["href", "text"], limit: 300 });
const hits = links.items.filter(a => /discuss|community|forum/i.test((a.href||"") + " " + (a.text||"")));
return { total: links.total, hits };

const r = phi.goto("https://discussions.flightaware.com/");
const o = phi.observe();
return { url: r.url, title: r.title, total: o.total, nodes: o.nodes.map(n => `${n.ref}. ${n.role} "${n.text}"`).slice(0, 80) };

const r = phi.goto("https://discussions.flightaware.com/top?period=all");
const o = phi.observe();
const txt = phi.text();
return { url: r.url, title: r.title, nodes: o.nodes.map(n => `${n.ref}. ${n.role} "${n.text}"`).slice(0, 90), textSnippet: txt.slice(0, 1500) };

const o = phi.observe();
const nodes = o.nodes.map(n => ({ ref: n.ref, role: n.role, text: n.text, label: n.label, name: n.name, tag: n.tag, owner: n.owner }));
return { total: o.total, nodes: nodes.slice(0, 40) };

const r = phi.click(9);
phi.waitForNetworkIdle({ timeoutMs: 5000 });
const rows = phi.query("table tbody tr", { limit: 8 });
const txt = phi.text().slice(0, 900);
return { url: r.url, changed: r.changed, rows: rows.items, txt };

const o = phi.observe();
const nodes = o.nodes.filter(n => /Banter|replies|Replies/.test((n.name||"") + (n.text||""))).map(n => ({ref: n.ref, role: n.role, name: n.name, text: n.text}));
const rows = phi.query("table tbody tr", { limit: 3, fields: [] });
const hrefs = phi.query("table tbody tr a.raw-topic-link, table tbody tr td.main-link a", { limit: 3, fields: ["href"] });
const first = phi.query("table tbody tr", { limit: 1 });
return { nodes: nodes.slice(0,10), hrefs: hrefs.items, firstRow: first.items[0]?.text, activeSort: phi.query("th", {limit: 6}).items.map(t => t.text) };

const r = phi.click(12);
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const title = phi.query("h1", { limit: 1 }).items[0]?.text;
const posts = phi.query(".topic-post, .post-stream .topic-post", { limit: 5, fields: ["data-post-number"] });
const info = phi.js(() => {
  const t = document.title;
  const cnt = document.querySelector('#post_1 .post-notice, .topic-map, .posts-count, .number') ? null : null;
  const map = Array.from(document.querySelectorAll('.topic-map .number, .topic-map li')).slice(0,8).map(e => e.textContent.replace(/\s+/g,' ').trim());
  const replies = document.querySelector('[itemprop=interactionStatistic] .number, .replies .number');
  return { title: t, map, url: location.href, repliesText: replies ? replies.textContent.trim() : null };
});
return { navUrl: r.url, navigated: r.navigated, changedKeys: r.changed && Object.keys(r.changed), h1: title, postCount: posts.total, info };

const o = phi.observe();
const head = phi.query("h1", { limit: 2 }).items.map(i => i.text);
const map = phi.js(() => {
  const txt = (s) => { const e = document.querySelector(s); return e ? e.textContent.replace(/\s+/g,' ').trim() : null; };
  const likes = Array.from(document.querySelectorAll('.topic-map li, .topic-map .number')).slice(0,12).map(e => e.textContent.replace(/\s+/g,' ').trim());
  return { title: document.title, url: location.href, map: likes, posts: txt('.topic-map .posts'), cat: txt('.badge-category__name'), created: txt('.topic-map .topic-map-created, .topic-map time') };
});
const firstPost = phi.query(".topic-post .cooked, #post_1 .cooked", { limit: 1 }).items[0]?.text?.slice(0, 300);
return { url: o.url, title: o.title, total: o.total, head, map, firstPost };

const v = phi.js(() => {
  const t = (s) => { const e = document.querySelector(s); return e ? e.textContent.replace(/\s+/g,' ').trim() : null; };
  const mapItems = Array.from(document.querySelectorAll('.topic-map li')).slice(0,10).map(e => e.textContent.replace(/\s+/g,' ').trim());
  const title = document.querySelector('#topic-title h1, h1')?.textContent.trim();
  const count = document.querySelector('.topic-map .posts, .topic-map [title*="repl"]');
  return {
    title, url: location.href,
    mapItems,
    postsCountText: count ? count.textContent.replace(/\s+/g,' ').trim() : null,
    postNumbers: Array.from(document.querySelectorAll('.topic-post')).slice(0,3).map(p => p.id)
  };
});
phi.keep("answer", {
  forum: "https://discussions.flightaware.com/",
  allTimeTopSortedByReplies: "https://discussions.flightaware.com/top?ascending=false&order=posts&period=all",
  topRow: "The Banter Thread — General — 5.5k replies — 2.4M views",
  openedUrl: "https://discussions.flightaware.com/t/the-banter-thread/4412",
  openedTitle: "The Banter Thread - FlightAware / General - FlightAware Discussions",
  pageNumbers: v.mapItems,
  firstPostSnippet: "Just wanted to start a thread to consolidate all the off-topic banter that the regulars enjoy so much."
});
return v;

const v = phi.js(() => {
  const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const out = {};
  out.title = document.title;
  out.url = location.href;
  // Discourse topic map / stats
  const stats = Array.from(document.querySelectorAll('.topic-map__contents, .topic-map__stats, .topic-map')).slice(0,3).map(e => norm(e.textContent).slice(0, 400));
  out.stats = stats;
  // header area reply count
  const hdr = document.querySelector('.topic-header, .topic-title, #topic-title');
  out.headerText = hdr ? norm(hdr.textContent).slice(0, 300) : null;
  // post stream count
  out.postCount = document.querySelectorAll('#post_1, .topic-post').length;
  out.replyBtn = norm((document.querySelector('.topic-footer-main-buttons .btn, button.reply') || {}).textContent);
  return out;
});
return v;

const top = phi.js(async () => {
  const r = await fetch('/top.json?order=posts&period=all&ascending=false&per_page=8', { credentials: 'include' });
  const j = await r.json();
  return j.topic_list.topics.map(t => ({ title: t.title, posts: t.posts_count, views: t.views, id: t.id, slug: t.slug, replyCount: t.reply_count, like: t.like_count }));
});
const page = phi.js(async () => {
  const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const t = await fetch('/t/4412.json', { credentials: 'include' }).then(r => r.json());
  return { title: t.title, posts_count: t.posts_count, reply_count: t.reply_count, views: t.views, posts: t.post_stream?.stream?.length, cat: t.category_id };
});
phi.keep("top_posts", top);
phi.keep("thread_json", page);
return { top: top.slice(0, 4), page };

const v = phi.js(() => {
  const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const out = { title: document.title, url: location.href };
  // find "replies" label + number in header stats
  const labels = Array.from(document.querySelectorAll('.topic-map__labels, .topic-map__label, .topic-map__stat, .number, .topic-map__contents span, .topic-map__contents a')).map(e => norm(e.textContent)).filter(Boolean).slice(0, 30);
